'use strict';
// This review prototype uses synthetic in-memory data. It has no IPC or production API calls.
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={page:'launch',mode:'desktop',module:'DESIGN',product:'E3D 2.1',project:'DEMO',user:'DESIGNER',mdb:'/ALL',passwordSaved:true,settings:'用户目录',root:'Documents / YuzuhaWorkspace',category:'全部',app:'ELDATA 读取',data:[],filter:'',tablePage:1,sort:1,running:false,simulateError:false,binding:{method:'PhaytonObjectWalker.MatchLargeArr',target:'当前选中元素',attribute:'ELDATA'},collection:'个人笔记',note:1,notes:[{id:1,title:'大数组读取流程',tags:'PML · 经验',body:'先提取，再格式化\n\n大型数组需要保持完整的提取路径。拿到原始结果后，再统一格式化，并按下标遍历。\n\n验证时记录什么\n01   原始数组长度与提取长度\n02   首项、末项与下标范围\n03   错误、超时与会话状态',rev:3,archived:false},{id:2,title:'Form 按钮与回调',tags:'PMLFRM · 界面',body:'简单的输入与按钮可以使用原生 Form。表格、筛选和导出可以放在 HTML 界面中。\n\n界面按钮绑定到已登记的方法，参数与回调单独配置。',rev:1,archived:false},{id:3,title:'用户目录与升级',tags:'工作空间 · 运维',body:'项目、知识库、应用绑定与导出结果放在独立的用户目录。\n\n先预览目录变化，再复制、校验。升级包不携带用户数据，原数据保留。',rev:2,archived:false}],records:[],doc:'home',docTitle:'从读取 ELDATA 到结果表格'};
const button=(label,action,primary=false)=>`<button class="btn${primary?' primary':''}" data-action="${action}">${label}</button>`;
const head=(k,t,s,extra='')=>`<header class="page-head"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p class="subtitle">${s}</p></div>${extra}</header>`;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function record(title,detail,ok=true){state.records.unshift({title,detail,ok,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});$('#record-count').textContent=state.records.length}
let dialogCallbacks={};let lastFocus;
function modal(title,body,actions=[]){lastFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;dialogCallbacks={};$('#dialog-actions').innerHTML=actions.map((a,i)=>{dialogCallbacks[i]=a.fn;return `<button class="btn ${a.primary?'primary':''} ${a.danger?'danger':''}" data-dialog-action="${i}">${a.label}</button>`}).join('');if(!$('#dialog').open)$('#dialog').showModal()}
function closeModal(){$('#dialog').close();if(lastFocus?.isConnected)lastFocus.focus()}
$('#dialog-close').onclick=closeModal;
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function mode(m){state.mode=m;$('#window').hidden=m!=='desktop';$('#docs').hidden=m!=='docs';$('#restore-window').hidden=true;$$('.preview-bar [data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===m));if(m==='docs')renderDocs();else render()}
function go(p){state.page=p;mode('desktop');$('#main').focus({preventScroll:true})}
function render(){const renders={launch:launch,apps:apps,knowledge:knowledge,settings:settings,records:records};$('#main').innerHTML=`<div class="page-content">${renders[state.page]()}</div>`;$$('.sidebar [data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===state.page))}
function launch(){return head('01 / START YOUR WORK','打开工程，继续工作。','工程配置只填一次。选择模块，就可以开始今天的工作。')+`<div class="launch-grid"><section class="panel"><div class="panel-title"><div><h2>启动工程</h2><p class="subtitle">${state.product} / 本机配置</p></div>${button('切换产品','product')}</div><div class="form-grid"><label class="wide">项目名称<input id="project" value="${esc(state.project)}" autocomplete="off" placeholder="输入项目代码"></label><label>用户名<input id="username" value="${esc(state.user)}" autocomplete="off"></label><label>密码<input id="password" type="password" value="${state.passwordSaved?'demo-only':''}" autocomplete="off" placeholder="仅供预览，不保存真实密码"></label><label class="wide">MDB<input id="mdb" list="mdb-options" value="${esc(state.mdb)}"><datalist id="mdb-options"><option>/ALL</option><option>/DESIGN</option><option>/CATALOGUE</option></datalist></label><div class="wide"><label>模块</label><div class="segmented">${['DESIGN','PARAGON','DRAW'].map(s=>`<button data-module="${s}" class="${s===state.module?'active':''}">${s}</button>`).join('')}<button data-action="more-modules">${['DESIGN','PARAGON','DRAW'].includes(state.module)?'更多 ▾':esc(state.module)+' ▾'}</button></div></div></div><div class="launch-options"><label><input type="checkbox" id="remember" ${state.passwordSaved?'checked':''}>记住本机密码</label><button class="text-btn" data-action="advanced">高级启动选项 ›</button></div><footer class="panel-footer"><small>每次启动：REHASH ALL · 记录日志</small>${button('启动工程 ↗','launch',true)}</footer></section><aside class="recent-area"><h3 class="recent-title">最近使用</h3>${[['DEMO / 设计','E3D 2.1 · DESIGN','今天','DEMO','DESIGN'],['MARINE / 船舶','AM 12.1 · DESIGN','昨天','MARINE','DESIGN'],['DEMO / 元件库','E3D 2.1 · PARAGON','周三','DEMO','PARAGON']].map((a,i)=>`<button class="recent ${i===0?'active':''}" data-recent="${i}"><b>${a[0]}</b><small><span>${a[1]}</span><span>${a[2]}</span></small></button>`).join('')}<div class="feature"><h2>从一个小工具开始</h2><p>将 PML 和 HTML 连接起来。<br>参数、运行结果和文档，各有位置。</p><button class="text-btn" data-go="apps">浏览应用 →</button></div></aside></div><p class="note">无需重新填写路径。程序和参数可以在高级选项中调整。</p>`}
function captureLaunch(){state.project=$('#project')?.value.trim()||state.project;state.user=$('#username')?.value.trim()||state.user;state.mdb=$('#mdb')?.value.trim()||state.mdb}
function apps(){const items=[['ELDATA 读取','HTML · 数组与表格','数据读取'],['属性浏览器','HTML · 批量属性','数据读取'],['基础 Form','PMLFRM · 输入与操作','原生界面']].filter(a=>state.category==='全部'||a[2]===state.category);return head('02 / APPS & RESULTS','一个入口，连接你的工具。','选择应用、检查参数、查看结果。原生 Form 和 HTML 应用统一管理。',button('＋ 添加应用','add-app',true))+`<div class="app-grid"><aside class="panel app-list"><h3>全部应用</h3><div class="tabs">${['全部','数据读取','原生界面'].map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}">${c}</button>`).join('')}</div>${items.map(a=>`<button class="app-card ${state.app===a[0]?'active':''}" data-app="${a[0]}"><b>${a[0]}</b><small>${a[1]}</small></button>`).join('')}<button class="text-btn" data-action="categories">管理分类 ›</button></aside><section class="panel"><div class="panel-title"><div><h2>${state.app}</h2><p class="subtitle">演示应用 / 不连接 AVEVA</p></div>${button('按钮绑定','binding')}</div>${state.app==='ELDATA 读取'?`<div class="parameter"><div><small>读取目标</small><b>${esc(state.binding.target)}</b></div>${button(state.running?'正在读取…':'读取演示数据 →','read',true)}</div><div class="steps"><span class="${state.data.length?'done':''}" id="step1">01 VAR SPLIT 提取</span><span>→</span><span class="${state.data.length?'done':''}" id="step2">02 结果格式化</span><span>→</span><span class="${state.data.length?'done':''}" id="step3">03 下标遍历</span></div><div id="result-area">${resultTable()}</div>`:`<div class="empty"><b>${state.app==='基础 Form'?'原生 Form 入口':'属性浏览入口'}</b><p>此原型用于评审分类和绑定方式。<br>运行时沿用程序内现有的 PML 调用。</p><button class="btn" style="margin-top:25px" data-action="binding">查看按钮与参数</button></div>`}</section></div>`}
function resultTable(){if(!state.data.length)return `<div class="empty"><b>结果将在这里呈现</b><p>点击“读取演示数据”，体验提取、格式化和下标遍历。<br>本预览使用 32 条合成数据。</p></div>`;let rows=state.data.filter(a=>`${a.index} ${a.value} ${a.type}`.toLowerCase().includes(state.filter.toLowerCase())).sort((a,b)=>(a.index-b.index)*state.sort);let pages=Math.max(1,Math.ceil(rows.length/7));state.tablePage=Math.min(state.tablePage,pages);return `<div class="table-toolbar"><div><h3>结果表格 <small>${rows.length} 条记录</small></h3></div><div class="inline"><input id="table-filter" aria-label="筛选表格" placeholder="筛选结果…" value="${esc(state.filter)}">${button('导出 CSV','export')}</div></div><table><thead><tr><th><button data-action="sort">下标 ${state.sort===1?'↑':'↓'}</button></th><th>值</th><th>类型</th></tr></thead><tbody>${rows.slice((state.tablePage-1)*7,state.tablePage*7).map(r=>`<tr><td>${String(r.index).padStart(2,'0')}</td><td>${r.value}</td><td>${r.type}</td></tr>`).join('')||'<tr><td colspan="3">没有匹配的记录</td></tr>'}</tbody></table><div class="pagination"><span>演示结果 / 每页 7 条</span><span><button data-action="prev" ${state.tablePage===1?'disabled':''} aria-label="上一页">‹</button> ${state.tablePage} / ${pages} <button data-action="next" ${state.tablePage===pages?'disabled':''} aria-label="下一页">›</button></span></div>`}
async function runDemo(){if(state.running)return;state.running=true;state.data=[];render();const readButton=$('[data-action=read]');readButton.disabled=true;for(let i=1;i<=3;i++){await new Promise(r=>setTimeout(r,360));if(state.page==='apps'&&$('#step'+i))$('#step'+i).classList.add('done')};if(state.simulateError){state.running=false;record('读取演示失败','模拟 IPC 超时；没有自动重试。',false);if(state.page==='apps'){render();$('#result-area').innerHTML='<div class="error" role="alert">模拟连接超时。结果尚未取得；请先检查连接，再手动重试。</div>'}toast('模拟失败已记录；未执行真实 PML');return}state.data=Array.from({length:32},(_,i)=>({index:i+1,value:(i<7?[0,1240,360,0,880.5,42,1][i]:Math.round(Math.sin(i)*100000)/100).toFixed(3),type:'REAL'}));state.running=false;state.tablePage=1;record('ELDATA 演示读取','32 项提取 → 32 项格式化 → 下标 1…32 验证。');if(state.page==='apps')render();toast('32 条演示记录已就绪')}
function knowledge(){const list=state.notes.filter(n=>state.collection==='归档'?n.archived:!n.archived);const current=state.notes.find(n=>n.id===state.note&&!n.archived===(state.collection!=='归档'))||list[0];if(current)state.note=current.id;return head('03 / KNOWLEDGE','知识随手记录，也随时找到。','官方参考、自建资料和个人笔记拥有各自清楚的来源。',button('＋ 新建笔记','new-note',true))+`<section class="panel knowledge-grid"><aside class="collections"><h3>资料空间</h3>${['全部内容','个人笔记','官方参考','我的资料源','归档'].map(c=>`<button data-collection="${c}" class="${state.collection===c?'active':''}">${c}${c==='个人笔记'?'　'+state.notes.filter(n=>!n.archived).length:''}</button>`).join('')}</aside><div class="note-list"><input id="note-search" aria-label="搜索笔记" placeholder="搜索标题、标签或正文…">${list.map(n=>`<button class="note-item ${n.id===current?.id?'active':''}" data-note="${n.id}" data-search="${esc(n.title+' '+n.tags+' '+n.body)}"><b>${esc(n.title)}</b><small>${esc(n.tags)}</small><small>修订 ${n.rev} · 演示内容</small></button>`).join('')}</div><article class="note-detail">${current?`<div class="eyebrow">个人笔记 / ${esc(current.tags)}</div><div class="detail-heading inline between"><h2>${esc(current.title)}</h2>${!current.archived?`<button class="btn" data-edit-note="${current.id}">编辑</button>`:''}</div><small>修订 ${current.rev} · 内容保存在本次预览内存中</small><div class="note-body">${esc(current.body)}</div>${current.id===1?'<pre><code>var !eell split $!lastfixArr of $!ob</code></pre>':''}<div class="panel-footer"><button class="text-btn" data-action="history">查看修订记录</button><button class="text-btn" data-archive="${current.id}">${current.archived?'恢复笔记':'归档笔记'}</button></div>`:'<div class="empty"><b>这里还没有笔记</b><p>新建一篇笔记，或从归档恢复内容。</p></div>'}</article></section>`}
function noteEditor(id){const n=state.notes.find(x=>x.id===id);modal(n?'编辑笔记':'新建笔记',`<label>标题<input id="edit-title" value="${esc(n?.title||'')}"></label><label>标签<input id="edit-tags" value="${esc(n?.tags||'PML · 经验')}"></label><label>正文<textarea id="edit-body" rows="9">${esc(n?.body||'')}</textarea></label><p>只保存本次预览中的演示笔记，刷新页面会恢复初始示例。</p>`,[{label:'取消',fn:closeModal},{label:'保存笔记',primary:true,fn:()=>{const title=$('#edit-title').value.trim(),body=$('#edit-body').value.trim(),tags=$('#edit-tags').value.trim();if(!title||!body){toast('请填写标题和正文');return}if(n){n.history??=[];n.history.push({rev:n.rev,title:n.title,body:n.body});Object.assign(n,{title,body,tags,rev:n.rev+1})}else{state.notes.unshift({id:Date.now(),title,body,tags,rev:1,archived:false})}state.note=n?.id||state.notes[0].id;state.collection='个人笔记';record('笔记已保存',title+'（预览内存）');closeModal();render();toast('笔记已保存 · 可查看修订记录')}}])}
function settings(){const tabs=['用户目录','外观与交互','启动行为','账户与凭据'];let body='';if(state.settings==='用户目录')body=`<section class="panel"><h2>统一用户目录</h2><p class="subtitle">推荐将用户资料保存在文档目录，也可以选择自己的位置。</p><div class="path-input"><input id="user-root" aria-label="统一用户目录" value="${esc(state.root)}">${button('推荐默认路径','default-root')}</div><div class="folder-grid">${['Projects　项目','Knowledge　知识库','Apps　应用与绑定','UserPmlLib　PML','Exports　导出结果'].map(s=>`<span>▱　${s}</span>`).join('')}</div><footer class="panel-footer"><small>先预览文件变化，再复制并核验；原文件保留。</small>${button('预览目录变更 →','migration',true)}</footer></section><div class="callout"><h2>更新程序时，保留用户数据</h2><p>安装包不携带知识库、应用绑定和个人资料。同名文件存在修改时，先停止并报告。</p><button class="text-btn" data-article="用户目录与升级">查看升级与备份说明 ↗</button></div>`;
if(state.settings==='外观与交互')body=`<section class="panel"><h2>舒适的日常工作空间</h2><div class="settings-row"><div><h3>外观</h3><p class="subtitle">日常操作使用浅色，保持清楚的对比。</p></div><span class="tag">浅色 · 本轮设计</span></div><div class="settings-row"><div><h3>减少动态效果</h3><p class="subtitle">取消页面位移和渐变，保留明确的状态变化。</p></div><label class="inline"><input type="checkbox" id="reduce-motion" ${document.body.classList.contains('reduce-motion')?'checked':''}>启用</label></div><div class="settings-row"><div><h3>自绘窗口</h3><p class="subtitle">统一标题栏、搜索与窗口操作的视觉样式。</p></div><button class="text-btn" data-action="chrome-notes">查看交互约定</button></div></section>`;
if(state.settings==='启动行为')body=`<section class="panel"><h2>每次启动前做什么</h2><div class="settings-row"><div><h3>PML REHASH ALL</h3><p class="subtitle">切换 AM / E3D 后重新建立索引，并记录执行结果。</p></div><span class="tag">沿用现有设置</span></div><p class="note">生产版启动策略由现有配置与环境变量控制。本原型不会改动它们。</p><button class="text-btn" data-article="启动行为与 REHASH">阅读特殊启动记录 ↗</button></section>`;
if(state.settings==='账户与凭据')body=`<section class="panel"><h2>本机凭据</h2><div class="settings-row"><div><h3>保存的密码</h3><p class="subtitle">${state.passwordSaved?'示例工程保存了演示凭据。':'当前没有保存的演示密码。'}</p></div><span class="tag">${state.passwordSaved?'已保存':'未保存'}</span></div><p class="note">真实密码由 Windows 凭据管理器保管。此预览不读取或更改真实凭据。</p><div style="margin-top:30px">${button('清除保存的密码…','clear-password')}</div></section>`;
return head('SETTINGS / DATA & PREFERENCES','你的数据，留在你的目录。','程序可以更新。项目、知识和个人配置都有独立的位置。')+`<div class="panel settings-tabs"><div class="tabs">${tabs.map(t=>`<button data-setting="${t}" class="${state.settings===t?'active':''}">${t}</button>`).join('')}</div></div>${body}`}
function records(){return head('04 / ACTIVITY','每一步，都有迹可循。','查看这次预览中的操作。真实运行记录需要连接实际程序。',button('清空演示记录','clear-records'))+`<section class="panel">${state.records.length?state.records.map((r,i)=>`<div class="record"><span class="status-icon">${r.ok?'✓':'!'}</span><div><b>${esc(r.title)}</b><small>${esc(r.detail)}</small></div><button class="text-btn" data-record="${i}">${r.time}　查看详情 ›</button></div>`).join(''):'<div class="empty"><b>还没有运行记录</b><p>试着启动演示工程、读取数据或保存笔记。</p><button class="text-btn" data-go="apps">打开应用 →</button></div>'}</section>`}
function docHeader(){return `<header class="doc-nav"><button class="doc-brand" data-doc="home"><span class="logo">Y</span>Yuzuha / Docs</button>${['开始使用','开发指南','API 参考','更新记录'].map((s,i)=>`<button data-doc="${['home','article','api','updates'][i]}" class="${state.doc===['home','article','api','updates'][i]?'active':''}">${s}</button>`).join('')}<button class="doc-search" data-action="search">搜索文档… <kbd>Ctrl K</kbd></button></header>`}
function renderDocs(){let html='';if(state.doc==='home')html=`<div class="doc-home"><section class="hero"><div><div class="eyebrow">BUILD WITH YUZUHA</div><h1>让工具，更贴近你的工作。</h1><p>从连接 AVEVA 到自己的 PML 与 HTML 应用。<br>每个步骤都有解释，每次运行都有依据。</p><div class="inline">${button('从这里开始 →','start-guide',true)}<button class="btn" data-doc="api">浏览 API</button></div></div><div class="diagram"><div class="eyebrow">YOUR WORKSPACE</div><div class="diagram-box">HTML / 原生 Form</div><div class="diagram-arrow">↓</div><div class="diagram-box">Yuzuha · 参数与 IPC</div><div class="diagram-arrow">↓</div><div class="diagram-box">PML FUNCTION / OBJECT</div></div></section><h2 class="guide-heading">按你现在要做的事，找到下一步。</h2><div class="guide-cards">${[['01','连接与启动','安装、工程配置、会话连接。<br>先让熟悉的工作顺畅起来。','开始使用'],['02','开发一个工具','Form、Function、Object 与 HTML。<br>把一个想法变成可重复的操作。','从读取 ELDATA 到结果表格'],['03','理解运行结果','参数、数据、日志与验证。<br>知道发生了什么，才方便改进。','运行结果与错误排查']].map(a=>`<button class="guide-card" data-article="${a[3]}"><span class="eyebrow">${a[0]}</span><h2>${a[1]}</h2><p>${a[2]}</p><span class="link">${a[0]==='02'?'开发指南':a[0]==='03'?'查看排查指南':'开始使用'} →</span></button>`).join('')}</div><div class="doc-shortcuts"><h3>常用参考</h3><div class="inline"><button class="text-btn" data-doc="api">PML 对象与方法 ↗</button><button class="text-btn" data-article="CLI 命令参考">CLI 命令 ↗</button><button class="text-btn" data-article="用户目录与升级">用户目录与升级 ↗</button></div></div><footer class="doc-footer">Yuzuha Documentation / 设计预览 · 内容示例</footer></div>`;else html=docArticle();$('#docs').innerHTML=`<div class="doc-shell page-content">${docHeader()}${html}</div>`}
const articles={
'从读取 ELDATA 到结果表格':{sub:'把数据获取、格式化和下标遍历拆成可检查的步骤。',intro:'HTML 按钮提交参数，程序通过现有 IPC 调用 PML。PML 完成数组提取，再将结果交回界面进行分页和导出。',title:'01　保留 VAR SPLIT 提取',body:'数组规模较大时，保留已验证的提取方式。先取得完整数据，再将值转换成统一的结果结构。',code:'var !eell split $!lastfixArr of $!ob',next:'02　检查结果与下标范围',last:'记录长度、首末项与失败信息。超时后先查看会话状态。此处展示的是交互设计示例，并不代表本轮完成 AVEVA 实测。'},
'用户目录与升级':{sub:'程序文件和用户资料，各自拥有明确的位置。',intro:'在设置中选择推荐目录或自己的资料目录。先预览文件变化，复制并核验完成后，再保存新路径；原文件保留。',title:'01　资料目录',body:'Projects 保存项目，Knowledge 保存知识，Apps 保存应用与绑定，UserPmlLib 保存自己的 PML，Exports 保存导出结果。',code:'Documents / YuzuhaWorkspace',next:'02　升级保护',last:'升级包不携带用户资料。程序文件存在本地修改时停止覆盖。运行中的客户端和知识库需要先关闭。'},
'开始使用':{sub:'先完成连接，再运行自己的第一个工具。',intro:'安装 Yuzuha 后，选择本机产品，填写项目和账户，选择 MDB 与模块。已保存的配置可直接复用。',title:'01　选择工程',body:'日常模式只显示必要信息。程序路径、初始化文件和特殊启动行为收在高级选项中。',code:'项目 / 用户名 / 密码 / MDB / 模块',next:'02　验证连接',last:'从连接状态进入会话详情。先读取少量数据验证，再逐步执行需要的操作。'},
'运行结果与错误排查':{sub:'失败可解释，下一步可选择。',intro:'运行记录展示发起时间、目标、输入摘要与结果。读取超时后先检查 AVEVA 状态，不自动重放可能有副作用的操作。',title:'01　检查状态',body:'区分未连接、正在执行、已完成、超时和失败。不要用一个笼统的健康度替代实际问题。',code:'目标 → 参数 → 执行 → 回执',next:'02　保留证据',last:'记录每一步的状态与错误文本，方便复验。真实数据和凭据不放进公开报告。'},
'CLI 命令参考':{sub:'命令行入口与桌面共同使用已有服务。',intro:'CLI 可以用于自动化工作流和本机 HTML 管理器入口。具体参数以已安装版本的帮助和正式文档为准。',title:'01　打开 HTML 管理器',body:'桌面按钮和 CLI 可以打开独立浏览器页面。WebView 嵌入是另一项可以评审的宿主选择。',code:'YuzuhaToolkit.Mcp.exe --cli web open',next:'02　CLI 与 MCP',last:'CLI 适合脚本与终端；MCP 提供客户端工具发现。此设计不要求改变现有注册方式。'},
'启动行为与 REHASH':{sub:'特殊启动动作需要有明确来源与记录。',intro:'保留每次启动执行 REHASH ALL 的既有策略。AM/E3D 切换后重新建立索引，并在日志中记录本次动作。',title:'01　明确启动策略',body:'生产程序继续使用现有环境变量和桌面配置。预览不会修改它们。',code:'YUZUHA_STARTUP_ACTIONS=rehash-all',next:'02　核对真实日志',last:'安装成功不等于新会话已经执行启动动作；重新启动 AVEVA 后再核对日志。'}};
function docArticle(){let title=state.doc==='api'?'API 参考':state.doc==='updates'?'更新记录':state.docTitle;let a=articles[title]||articles['从读取 ELDATA 到结果表格'];const toc=['开发起点','PML 基础','Function 与 Object','原生 Form','HTML 应用','按钮与参数绑定','数据提取与表格','部署与验证','错误处理'];let body=state.doc==='api'?`<h2>按功能查找接口</h2><p>真实签名与 XML 注释继续由 DocFX 从代码生成。此页仅展示分类与阅读样式。</p><table><thead><tr><th>分类</th><th>入口</th><th>用途</th></tr></thead><tbody>${[['PML Object','PhaytonObjectWalker','对象取值、格式化与遍历'],['PML Function','YuzuhaReadCurrentElement','当前元素读取'],['Workspace','UserDataPaths','统一用户目录'],['Knowledge','KnowledgeRepository','个人笔记与修订']].map(r=>`<tr><td>${r[0]}</td><td><button class="text-btn" data-article="${r[0]==='Workspace'?'用户目录与升级':'从读取 ELDATA 到结果表格'}">${r[1]}</button></td><td>${r[2]}</td></tr>`).join('')}</tbody></table>`:state.doc==='updates'?`<h2>2026.10 / 设计预览 R1</h2><p>按工作任务归并导航；浅色启动页；原生 Form 与 HTML 统一管理入口；知识库阅读与编辑；独立用户目录设置。</p><div class="callout"><h3>设计阶段</h3><p>此页面不是生产版发布公告。新版界面尚未替换已安装桌面或正式 DocFX 站点。</p></div>`:`<h2>先理解这条链路</h2><p>${a.intro}</p><div class="pipeline"><b>按钮与参数</b><span>→</span><b>IPC / PML</b><span>→</span><b>结果表格</b></div><h2 id="step-one">${a.title}</h2><p>${a.body}</p><div class="code-label"><span>PML / 示例</span><button class="text-btn" data-action="copy-code">复制</button></div><pre><code id="article-code">${esc(a.code)}</code></pre><h2 id="step-two">${a.next}</h2><p>${a.last}</p>`;return `<div class="doc-layout"><aside class="doc-toc"><h3>开发指南</h3>${toc.map((s,i)=>`<button class="${i===6?'active':''}" data-article="${i===0?'开始使用':i>=7?'运行结果与错误排查':'从读取 ELDATA 到结果表格'}">${s}</button>`).join('')}<button data-doc="home">← 返回文档首页</button></aside><article class="doc-article"><div class="eyebrow">${state.doc==='api'?'REFERENCE':'开发指南 / HTML 应用'}</div><h1>${title}</h1><p>${state.doc==='api'?'从任务出发，定位对象、方法与参数。':state.doc==='updates'?'界面与体验的版本记录。':a.sub}</p><div class="doc-meta">阅读约 6 分钟 · PML / HTML · 示例文章</div><section id="intro">${body}</section><div class="article-next"><button class="text-btn" data-doc="home">← 文档首页</button><button class="text-btn" data-mode="desktop">打开工作台预览 ↗</button></div></article><aside class="on-this-page"><b>本页内容</b><a href="#intro">理解链路</a><a href="#step-one">提取与配置</a><a href="#step-two">结果与验证</a><br><b>关联参考</b><button class="text-btn" data-doc="api">API 参考</button><button class="text-btn" data-article="CLI 命令参考">CLI 命令</button></aside></div>`}
function showSearch(){modal('搜索工作台与文档','<input id="search-query" aria-label="搜索工作台与文档" placeholder="输入关键字，例如：目录、PML、知识库…"><div id="search-results"></div>');updateSearch('');$('#search-query').addEventListener('input',e=>updateSearch(e.target.value));$('#search-query').focus()}
function updateSearch(q){const items=[['工作台','launch','工程与模块'],['应用','apps','读取与结果表格'],['知识库','knowledge','笔记和参考资料'],['设置','settings','用户目录与凭据'],...Object.keys(articles).map(s=>[s,'article','文档 · 开发与使用'])].filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase()));$('#search-results').innerHTML=items.map(x=>`<button class="search-result" data-search-page="${x[1]}" data-title="${x[0]}">${x[0]}<small>${x[2]}</small></button>`).join('')||'<p>没有匹配结果，试试“目录”或“PML”。</p>'}
const actions={
product(){captureLaunch();modal('选择本机产品','<p>此处为可选产品样式，使用演示列表。</p><label>产品<select id="product-select"><option>E3D 2.1</option><option>E3D 3.1</option><option>AM 12.1</option><option>PDMS 12.1</option></select></label>',[{label:'取消',fn:closeModal},{label:'使用此产品',primary:true,fn:()=>{state.product=$('#product-select').value;closeModal();render()}}]);$('#product-select').value=state.product},
'more-modules'(){captureLaunch();modal('选择模块',`<p>常用模块可直接选择，无需手写参数。</p><label>模块<select id="module-select">${['DESIGN','PARAGON','DRAW','ISODRAFT','SPECON','ADMIN'].map(s=>`<option>${s}</option>`).join('')}</select></label>`,[{label:'取消',fn:closeModal},{label:'选择模块',primary:true,fn:()=>{state.module=$('#module-select').value;closeModal();render()}}])},
advanced(){captureLaunch();modal('高级启动选项','<p>日常启动不需要重新填写这些项目。</p><label>启动入口<input value="LaunchDesk / 已配置入口" readonly></label><label>初始化配置<input value="沿用已安装产品的 INIT / BAT" readonly></label><label>启动前动作<select><option>REHASH ALL · 记录日志</option></select></label><p>本次预览不修改真实路径或环境变量。</p>',[{label:'完成',primary:true,fn:closeModal}])},
launch(){if(!$('#project').value.trim()||!$('#username').value.trim()){toast('请填写项目名称和用户名');return}captureLaunch();modal('启动工程预览',`<p>项目 <b>${esc(state.project)}</b> · ${esc(state.product)} · ${state.module}</p><p>MDB：${esc(state.mdb)}<br>启动前动作：REHASH ALL<br>日志：记录本次启动结果</p><div class="callout"><h3>交互演示</h3><p>点击后只生成演示运行记录，不启动 AM/E3D。</p></div>`,[{label:'返回修改',fn:closeModal},{label:'模拟启动',primary:true,fn:()=>{record('工程启动演示',state.project+' / '+state.module+' · 未启动实际客户端');closeModal();toast('启动演示完成 · 可到运行记录查看')}}])},
'add-app'(){modal('添加应用',`<label>应用名称<input id="new-app-name" placeholder="例如：批量属性表"></label><label>界面形式<select id="app-type"><option>HTML 页面</option><option>原生 PML Form</option></select></label><label>分类<select><option>数据读取</option><option>原生界面</option><option>项目工具</option></select></label><p>评审版本演示注册步骤，不写入真实应用清单。</p>`,[{label:'取消',fn:closeModal},{label:'预览注册',primary:true,fn:()=>{if(!$('#new-app-name').value.trim()){toast('请填写应用名称');return}const name=$('#new-app-name').value;closeModal();record('应用注册预览',name+' · 生产注册未执行');toast('已记录注册预览：'+name)}}])},
categories(){modal('应用分类','<p>按用途查找，界面类型作为辅助标记。</p><label>分类名称<input value="数据读取 · 原生界面 · 项目工具" id="category-names"></label>',[{label:'完成',primary:true,fn:()=>{closeModal();toast('分类编辑流程已演示')}}])},
binding(){modal('按钮绑定与参数',`<div class="tag">${esc(state.app)} / 读取按钮</div><label>PML 方法<select id="binding-method"><option>PhaytonObjectWalker.MatchLargeArr</option><option>YuzuhaReadCurrentElement</option></select></label><label>目标参数<input id="binding-target" value="${esc(state.binding.target)}"></label><label>属性<input id="binding-attribute" value="${esc(state.binding.attribute)}"></label><label class="inline"><input id="simulate-error" type="checkbox" ${state.simulateError?'checked':''}>模拟超时，查看失败状态</label><p>现有 IPC 负责实际调用。本原型仅配置演示绑定。</p>`,[{label:'取消',fn:closeModal},{label:'保存演示绑定',primary:true,fn:()=>{state.binding={method:$('#binding-method').value,target:$('#binding-target').value,attribute:$('#binding-attribute').value};state.simulateError=$('#simulate-error').checked;closeModal();render();toast('演示绑定已更新')}}]);$('#binding-method').value=state.binding.method},
read:runDemo,
export(){const csv='\uFEFFIndex,Value,Type\r\n'+state.data.filter(a=>`${a.index} ${a.value} ${a.type}`.toLowerCase().includes(state.filter.toLowerCase())).sort((a,b)=>(a.index-b.index)*state.sort).map(r=>[r.index,r.value,r.type].join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='Yuzuha-ELDATA-demo.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);record('导出 CSV 演示','导出当前筛选的合成记录');toast('已导出合成数据 CSV')},
sort(){state.sort*=-1;$('#result-area').innerHTML=resultTable()},prev(){state.tablePage--;$('#result-area').innerHTML=resultTable()},next(){state.tablePage++;$('#result-area').innerHTML=resultTable()},
'new-note'(){noteEditor()},
history(){const n=state.notes.find(x=>x.id===state.note)||state.notes[0];modal('修订记录',`<p>当前修订 ${n.rev} · ${esc(n.title)}</p>${(n.history||[]).map(r=>`<div class="callout"><h3>修订 ${r.rev} · ${esc(r.title)}</h3><p>${esc(r.body.slice(0,180))}</p></div>`).join('')||'<p>初始示例没有附带历史正文。编辑保存后，可在此查看上一版内容。</p>'}`,[{label:'返回',primary:true,fn:closeModal}])},
'default-root'(){$('#user-root').value='Documents / YuzuhaWorkspace';toast('已填入推荐路径，尚未切换')},
migration(){const root=$('#user-root').value.trim();if(!root){toast('请选择用户目录');return}modal('目录变更预览',`<p>目标：<b>${esc(root)}</b></p><table><thead><tr><th>目录</th><th>动作</th></tr></thead><tbody><tr><td>Knowledge</td><td>复制并核验示例资料</td></tr><tr><td>Apps</td><td>保留绑定</td></tr><tr><td>原目录</td><td>保留</td></tr></tbody></table><div class="callout"><p>这是交互演示，不访问文件系统，不迁移真实数据。</p></div>`,[{label:'取消',fn:closeModal},{label:'确认演示切换',primary:true,fn:()=>{state.root=root;record('用户目录切换演示',root+' · 没有移动真实文件');closeModal();render();toast('已切换演示目录')}}])},
'clear-password'(){modal('清除保存的密码？','<p>清除后，下次启动需要重新输入密码。项目、用户名与 MDB 保留。</p><p>此原型只清除演示状态，不访问 Windows 凭据管理器。</p>',[{label:'保留密码',fn:closeModal},{label:'清除演示密码',danger:true,fn:()=>{state.passwordSaved=false;record('清除演示密码','真实凭据未改变');closeModal();render();toast('演示密码已清除')}}])},
'clear-records'(){modal('清空演示记录？','<p>只清空此页面的演示操作，不影响程序日志。</p>',[{label:'取消',fn:closeModal},{label:'清空',fn:()=>{state.records=[];$('#record-count').textContent='';closeModal();render()}}])},
'chrome-notes'(){modal('自绘窗口的交互约定','<p>生产落地需保留标题栏拖动、双击最大化、边缘缩放、系统菜单、Alt+Space 与 Windows Snap。按钮提供可访问名称。</p><p>网页预览中的窗口按钮只调整预览面板；真实 Windows 窗口行为留待 WPF WindowChrome 集成时验证。</p>',[{label:'知道了',primary:true,fn:closeModal}])},
search:showSearch,'start-guide'(){state.doc='article';state.docTitle='开始使用';renderDocs()},
async 'copy-code'(){try{await navigator.clipboard.writeText($('#article-code').textContent);toast('代码示例已复制')}catch{toast('浏览器未允许复制；可以直接选中文本')}}
};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.dialogAction!==undefined){dialogCallbacks[d.dialogAction]?.();return}if(d.mode){mode(d.mode);return}if(d.go){if(state.page==='launch')captureLaunch();go(d.go);return}if(d.module){captureLaunch();state.module=d.module;render();return}if(d.recent!==undefined){const i=+d.recent;state.project=i===1?'MARINE':'DEMO';state.product=i===1?'AM 12.1':'E3D 2.1';state.module=i===2?'PARAGON':'DESIGN';render();return}if(d.app){state.app=d.app;render();return}if(d.category){state.category=d.category;render();return}if(d.setting){state.settings=d.setting;render();return}if(d.collection){if(d.collection==='官方参考'||d.collection==='我的资料源'){modal(d.collection,d.collection==='官方参考'?'<p>官方参考只读浏览，通过来源标记与个人笔记区分。</p><button class="btn" data-doc="api">浏览文档 API 参考 ↗</button>':'<p>资料源登记、索引重建和归档均应保留原文件。新版桌面已有资料源管理；这里展示阅读入口。</p>',[{label:'返回',fn:closeModal}]);return}state.collection=d.collection;render();return}if(d.note){state.note=+d.note;render();return}if(d.editNote){noteEditor(+d.editNote);return}if(d.archive){const n=state.notes.find(n=>n.id===+d.archive);modal(n.archived?'恢复笔记？':'归档笔记？',`<p>${esc(n.title)}</p><p>${n.archived?'恢复到个人笔记列表。':'保留正文与修订记录，可在“归档”中恢复。'}</p>`,[{label:'取消',fn:closeModal},{label:n.archived?'恢复':'归档',primary:true,fn:()=>{n.archived=!n.archived;closeModal();render();toast(n.archived?'已归档，可恢复':'已恢复')}}]);return}if(d.record){const r=state.records[+d.record];modal(r.title,`<p>${esc(r.detail)}</p><p>时间：${r.time} · ${r.ok?'完成':'失败'} · 演示记录</p>`,[{label:'关闭',fn:closeModal}]);return}if(d.searchPage){closeModal();if(d.searchPage==='article'){state.doc='article';state.docTitle=d.title;mode('docs')}else go(d.searchPage);return}if(d.doc){if($('#dialog').open)closeModal();state.doc=d.doc;mode('docs');return}if(d.article){state.doc='article';state.docTitle=d.article;mode('docs');return}if(d.action)actions[d.action]?.()});
document.addEventListener('input',e=>{if(e.target.id==='table-filter'){let input=e.target,pos=input.selectionStart;state.filter=input.value;state.tablePage=1;$('#result-area').innerHTML=resultTable();$('#table-filter').focus();$('#table-filter').setSelectionRange(pos,pos)}if(e.target.id==='note-search'){const q=e.target.value.toLowerCase();$$('.note-item').forEach(b=>b.hidden=!b.dataset.search.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.id==='reduce-motion')document.body.classList.toggle('reduce-motion',e.target.checked);if(e.target.id==='remember')state.passwordSaved=e.target.checked});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}});
$('#search-open').onclick=showSearch;$('#minimize').onclick=()=>{$('#window').hidden=true;$('#restore-window').hidden=false};$('#maximize').onclick=()=>$('#window').classList.toggle('expanded');$('#close-window').onclick=()=>{$('#window').hidden=true;$('#restore-window').hidden=false};$('#restore-window').onclick=()=>mode('desktop');
$('#design-notes').onclick=()=>modal('Clear Workspace / R1','<p>设计目标：减少寻找入口的时间，让启动、应用、知识和记录各有位置。日常浅色；主要动作低饱和绿；阅读区域留白；参数渐进展开。</p><p>桌面与 DocFX 共享色彩、字阶与组件。本原型包含导航、模块切换、按钮绑定、合成表格、笔记 CRUD、目录变更预览、凭据二次确认和文档检索。</p><p>动效：悬停 120 ms、页面 180 ms。支持系统减少动画偏好。EffectCraft 暂未接入。生产调用与当前安装界面均未改动。</p>',[{label:'开始体验',primary:true,fn:closeModal}]);
render();
